{
  "name": "UHFQA 超高频量子分析仪",
  "name_en": "UHFQA Quantum Analyzer",
  "manufacturer": "Zurich Instruments",
  "description": "这是一台 Zurich Instruments 的 UHFQA 超高频量子分析仪，用于量子比特读出与高速 IQ 数据采集。该驱动覆盖外部参考时钟同步、默认读出配置加载、AWG 触发采集、结果轮询读取，以及串扰矩阵、相关性、旋转和阈值等读出参数管理。",
  "description_en": "This is a Zurich Instruments UHFQA ultra-high-frequency quantum analyzer used for qubit readout and high-speed IQ data acquisition. The driver supports external reference clock synchronization, loading default readout settings, AWG-triggered acquisition, polling and retrieving results, and managing readout parameters such as crosstalk matrices, correlations, rotations, and thresholds.",
  "tag_hints": [
    "quantum readout",
    "UHFQA",
    "qubit measurement",
    "IQ acquisition",
    "AWG-triggered acquisition",
    "external reference clock",
    "crosstalk suppression"
  ],
  "actions": [
    {
      "action_name": "auto-acquisition",
      "description": "执行一次完整采集流程，按设定的样本数、平均次数、通道和模式获取测量数据。",
      "description_en": "Run a complete acquisition sequence and collect measurement data with the configured sample count, averages, channels, and mode."
    },
    {
      "action_name": "auto-acquisition_arm",
      "description": "布防采集流程，使仪器进入等待触发和读出准备状态。",
      "description_en": "Arm the acquisition process so the instrument is ready for triggering and readout."
    },
    {
      "action_name": "auto-acquisition_finalize",
      "description": "结束采集并清理采集相关状态。",
      "description_en": "Finalize the acquisition and clean up acquisition-related state."
    },
    {
      "action_name": "auto-acquisition_get",
      "description": "启动一次测量，等待完成后读取采集数据。",
      "description_en": "Start a measurement, wait for completion, and then read out the acquired data."
    },
    {
      "action_name": "auto-acquisition_initialize",
      "description": "初始化采集参数，检查 AWG 程序结构并配置读出与循环计数。",
      "description_en": "Initialize acquisition parameters, validate the AWG program structure, and configure readout and loop count."
    },
    {
      "action_name": "auto-acquisition_poll",
      "description": "轮询仪器采集结果，直到获得期望数量的样本数据。",
      "description_en": "Poll the instrument for acquisition results until the expected number of samples is available."
    },
    {
      "action_name": "auto-assure_ext_clock",
      "description": "确保仪器使用并锁定外部参考时钟。",
      "description_en": "Ensure that the instrument is using and locked to an external reference clock."
    },
    {
      "action_name": "auto-clear_errors",
      "description": "清除仪器当前错误状态。",
      "description_en": "Clear the current instrument error state."
    },
    {
      "action_name": "auto-clock_freq",
      "description": "读取仪器时钟频率。",
      "description_en": "Read the instrument clock frequency."
    },
    {
      "action_name": "auto-download_crosstalk_matrix",
      "description": "读取仪器中的串扰抑制矩阵。",
      "description_en": "Download the crosstalk suppression matrix from the instrument."
    },
    {
      "action_name": "auto-load_default_settings",
      "description": "加载默认读出配置，包括时钟、输出、触发和结果记录等设置。",
      "description_en": "Load default readout settings, including clock, outputs, triggers, and result logging configuration."
    },
    {
      "action_name": "auto-print_correlation_overview",
      "description": "打印相关性参数概览。",
      "description_en": "Print an overview of correlation parameters."
    },
    {
      "action_name": "auto-print_crosstalk_overview",
      "description": "打印串扰矩阵与串扰相关参数概览。",
      "description_en": "Print an overview of the crosstalk matrix and related crosstalk settings."
    },
    {
      "action_name": "auto-print_deskew_overview",
      "description": "打印通道去偏斜或时序校正参数概览。",
      "description_en": "Print an overview of channel deskew or timing correction parameters."
    },
    {
      "action_name": "auto-print_integration_overview",
      "description": "打印积分读出参数概览。",
      "description_en": "Print an overview of integration readout parameters."
    },
    {
      "action_name": "auto-print_overview",
      "description": "打印仪器关键参数总览。",
      "description_en": "Print a general overview of key instrument parameters."
    },
    {
      "action_name": "auto-print_rotations_overview",
      "description": "打印读出旋转参数概览。",
      "description_en": "Print an overview of readout rotation parameters."
    },
    {
      "action_name": "auto-print_thresholds_overview",
      "description": "打印判决阈值参数概览。",
      "description_en": "Print an overview of discrimination threshold parameters."
    },
    {
      "action_name": "auto-print_user_regs_overview",
      "description": "打印用户寄存器参数概览。",
      "description_en": "Print an overview of user register parameters."
    },
    {
      "action_name": "auto-reset_acquisition_params",
      "description": "重置采集相关参数到默认状态。",
      "description_en": "Reset acquisition-related parameters to their default state."
    },
    {
      "action_name": "auto-reset_correlation_params",
      "description": "重置相关性参数到默认状态。",
      "description_en": "Reset correlation parameters to their default state."
    },
    {
      "action_name": "auto-reset_crosstalk_matrix",
      "description": "重置串扰抑制矩阵到默认值。",
      "description_en": "Reset the crosstalk suppression matrix to its default values."
    },
    {
      "action_name": "auto-reset_rotation_params",
      "description": "重置读出旋转参数到默认状态。",
      "description_en": "Reset readout rotation parameters to their default state."
    },
    {
      "action_name": "auto-upload_crosstalk_matrix",
      "description": "上传串扰抑制矩阵到仪器。",
      "description_en": "Upload a crosstalk suppression matrix to the instrument."
    }
  ]
}

